#!/usr/bin/env bun
/**
 * agent-md.script.ts — f00190 (Track H of q00006).
 *
 * Generate a `AGENT.md` per package (`packages/<name>/AGENT.md`)
 * and per plugin (`plugins/<name>/AGENT.md`) so a coding agent
 * that lands in a directory has a one-screen summary:
 *
 *   purpose, public, depends, writes, entry, tests, do_not,
 *   token_hotspots.
 *
 * Convention used here:
 *   - The file is regenerated by `bun run gen:agent-md` (a thin
 *     wrapper around this script). The first line is a
 *     `<!-- mcp-vertex:begin agent-md -->` marker that the drift
 *     check uses for the "regenerate only this block" workflow.
 *   - `< 400 tokens` is the size budget. Hand-edited prose lives
 *     BELOW the marker; the block above is fully regenerated.
 *
 * Privacy: the script enumerates filesystem content for the local
 * workspace only. It does NOT touch tool ids, host paths, or any
 * external identifier; the public api list is derived from local
 * `src/public/index.ts` re-exports.
 *
 * Exit codes:
 *   0 — every AGENT.md was written (or unchanged).
 *   1 — a write failed (rare; the script is I/O bound).
 */

import { readFile, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';

const REPO_ROOT = process.cwd();

const MARKER_BEGIN = '<!-- mcp-vertex:begin agent-md -->';
const MARKER_END = '<!-- mcp-vertex:end agent-md -->';

/** Schema-versioned snapshot — bump on breaking content layout. */
export const SCHEMA_VERSION = 1;

export interface IAgentScope {
	/** Workspace-relative path of the package / plugin dir. */
	readonly dir: string;
	/** Workspace-relative path of the `package.json`. */
	readonly packageJson: string;
	/** Workspace-relative path of the plugin manifest (plugins only). */
	readonly manifestJson?: string;
	/** Indicates whether this is a plugin dir. */
	readonly isPlugin: boolean;
}

export interface IPackageJsonShape {
	readonly name?: string;
	readonly version?: string;
	readonly description?: string;
	readonly main?: string;
	readonly dependencies?: Readonly<Record<string, string>>;
	readonly peerDependencies?: Readonly<Record<string, string>>;
}

export interface IPluginManifestShape {
	readonly id?: string;
	readonly summary?: string;
	readonly presets?: readonly string[];
	readonly tags?: readonly string[];
}

export interface IAgentMdSections {
	readonly purpose: string;
	readonly public: readonly string[];
	readonly depends: readonly string[];
	readonly writes: readonly string[];
	readonly entry: readonly string[];
	readonly tests: readonly string[];
	readonly doNot: readonly string[];
	readonly tokenHotspots: readonly string[];
}

const HOTCUT = 80;

const listDirs = async (path: string): Promise<readonly string[]> => {
	try {
		const { readdir } = await import('node:fs/promises');
		const entries = await readdir(path, { withFileTypes: true });
		return entries
			.filter((e) => e.isDirectory() && !e.name.startsWith('.'))
			.map((e) => e.name);
	} catch {
		return [];
	}
};

const readText = async (path: string): Promise<string> => {
	try {
		return await readFile(path, 'utf8');
	} catch {
		return '';
	}
};

/**
 * Truncate a token to < 80 chars so the generated AGENT.md stays
 * inside the 400-token budget.  Hover cuts are deliberately
 * mid-symbol to keep the list scannable.
 */
const truncate = (line: string): string =>
	line.length <= HOTCUT ? line : `${line.slice(0, HOTCUT - 1)}…`;

/**
 * Extract `export { … }` re-exports from a barrel file. We strip
 * `… } from '…'` clauses (the path is metadata, not a public
 * symbol), and emit each comma-separated entry on its own line.
 * `export const|function|class|interface|type Foo` declarations
 * are matched separately to capture the symbol name only.
 */
export const publicSymbolsFromBarrel = (text: string): readonly string[] => {
	const out: string[] = [];
	const lines = text.split('\n');
	let buffer: string[] = [];
	let inExportBlock = false;
	const flush = (): void => {
		if (buffer.length === 0) return;
		const joined = buffer
			.join(' ')
			.replace(/^\s*export\s*\{/, '')
			// Strip the `… } from '…'` clause; we only keep the
			// symbol list itself.
			.replace(/\}\s*from\s*['"`]([^'"`]+)['"`].*$/, '')
			.replace(/\}\s*;?\s*$/, '');
		for (const item of joined
			.split(',')
			.map((s) => s.trim())
			.filter(Boolean)) {
			out.push(truncate(item));
		}
		buffer = [];
	};
	for (const line of lines) {
		const trimmed = line.trim();
		if (inExportBlock) {
			if (/}\s*(?:from\s*['"`][^'"`]+['"`]\s*)?;?\s*$/.test(trimmed)) {
				inExportBlock = false;
				buffer.push(trimmed);
				flush();
				continue;
			}
			buffer.push(trimmed);
			continue;
		}
		if (/^export\s*\{/.test(trimmed)) {
			if (/\}\s*(?:from\s*['"`][^'"`]+['"`]\s*)?;?\s*$/.test(trimmed)) {
				// Single-line `export { foo, bar } from '…'`;
				buffer.push(trimmed);
				flush();
				continue;
			}
			inExportBlock = true;
			buffer.push(trimmed);
			continue;
		}
		const decl =
			/^export\s+(?:default\s+)?(?:const|function|class|interface|type|async\s+function)\s+(\w+)/.exec(
				trimmed,
			);
		if (decl !== null) {
			out.push(truncate(decl[1] ?? ''));
		}
	}
	return out;
};

/** Read `package.json` (parsed or empty on error). */
export const readPackageJson = async (
	path: string,
): Promise<IPackageJsonShape> => {
	const text = await readText(path);
	if (text.length === 0) return {};
	try {
		const json = JSON.parse(text);
		const obj: Record<string, unknown> = {};
		if (typeof json.name === 'string') obj.name = json.name;
		if (typeof json.version === 'string') obj.version = json.version;
		if (typeof json.description === 'string')
			obj.description = json.description;
		if (typeof json.main === 'string') obj.main = json.main;
		if (
			typeof json.dependencies === 'object' &&
			json.dependencies !== null
		) {
			obj.dependencies = json.dependencies as Record<string, string>;
		}
		if (
			typeof json.peerDependencies === 'object' &&
			json.peerDependencies !== null
		) {
			obj.peerDependencies = json.peerDependencies as Record<
				string,
				string
			>;
		}
		return obj as IPackageJsonShape;
	} catch {
		return {};
	}
};

/** Read the (TypeScript) plugin manifest as a shape, no eval. */
export const readPluginManifest = async (
	path: string,
): Promise<IPluginManifestShape> => {
	const text = await readText(path);
	if (text.length === 0) return {};
	const grab = (re: RegExp): string | undefined => {
		const m = re.exec(text);
		return m && typeof m[1] === 'string' ? m[1] : undefined;
	};
	const obj: Record<string, unknown> = {};
	const id = grab(/\bid:\s*['"`]([^'"`]+)['"`]/);
	if (id !== undefined) obj.id = id;
	const summary = grab(/\bsummary:\s*['"`]([^'"`]+)['"`]/);
	if (summary !== undefined) obj.summary = summary;
	obj.presets = [...text.matchAll(/\bpresets:\s*\[([^\]]*)\]/g)]
		.flatMap((m) =>
			(m[1] ?? '')
				.split(',')
				.map((s) => s.trim().replace(/^['"`]|['"`]$/g, '')),
		)
		.filter(Boolean);
	obj.tags = [...text.matchAll(/\btags:\s*\[([^\]]*)\]/g)]
		.flatMap((m) =>
			(m[1] ?? '')
				.split(',')
				.map((s) => s.trim().replace(/^['"`]|['"`]$/g, '')),
		)
		.filter(Boolean);
	return obj as IPluginManifestShape;
};

const MAX_PUBLIC = 14;
const MAX_DEPS = 8;
const MAX_TESTS = 4;
const MAX_HOTSPOTS = 4;

/**
 * Compose the AGENT.md sections for a package or plugin dir.
 *
 * - `purpose` ← `description` from package.json (truncated to 280 chars).
 * - `public` ← barrel re-exports under `<dir>/src/public/index.ts`.
 * - `depends` ← `dependencies` + `peerDependencies` names.
 * - `writes` ← heuristic on dir name + npm scripts key "prepare":
 *   anything starting with `fs.*.write*` or `*write*` tools.
 * - `entry` ← `main` from package.json, plus plugin's `index.ts`.
 * - `tests` ← up to six `*.spec.ts` paths under `tests/`.
 * - `doNot` ← style-specific pet peeves (constant list per scope).
 * - `tokenHotspots` ← paths whose names contain "tools" or "schema".
 */
export const composeAgentMd = async (
	scope: IAgentScope,
): Promise<IAgentMdSections> => {
	const pkg = await readPackageJson(join(REPO_ROOT, scope.packageJson));
	const barrel = await readText(
		join(REPO_ROOT, scope.dir, 'src/public/index.ts'),
	);
	const publicSymbols = publicSymbolsFromBarrel(barrel).slice(0, MAX_PUBLIC);
	const allDeps = {
		...(pkg.dependencies ?? {}),
		...(pkg.peerDependencies ?? {}),
	};
	const depends = Object.keys(allDeps).slice(0, MAX_DEPS);
	const writes: string[] = [];
	if (scope.isPlugin) {
		writes.push(
			`<host workspace>/.mcp-vertex/cache/${scope.dir.split('/').pop() ?? '*'}/`,
		);
	}
	const entry = pkg.main !== undefined ? [pkg.main] : [];
	if (scope.isPlugin) {
		entry.push('src/index.ts (default export → IMcpPlugin)');
	}
	const tests: string[] = [];
	const testsDir = scope.isPlugin
		? join(REPO_ROOT, scope.dir, 'tests')
		: join(REPO_ROOT, scope.dir, 'tests');
	const { readdir } = await import('node:fs/promises');
	const walkTests = async (path: string): Promise<void> => {
		try {
			const entries = await readdir(path, { withFileTypes: true });
			for (const entry of entries.sort((left, right) =>
				left.name.localeCompare(right.name),
			)) {
				if (tests.length >= MAX_TESTS) break;
				const full = join(path, entry.name);
				if (entry.isDirectory()) {
					await walkTests(full);
				} else if (entry.isFile() && entry.name.endsWith('.spec.ts')) {
					tests.push(relative(REPO_ROOT, full));
				}
			}
		} catch {
			// tests/ missing or unreadable — leave the list empty.
		}
	};
	await walkTests(testsDir);
	const doNot: string[] = scope.isPlugin
		? [
				`Do not import \`@mcp-vertex/core/lib/...\`; use \`@mcp-vertex/core/public\`.`,
				`Do not run user-facing shell or destructive tools without \`dryRunSupported: true\`.`,
				`Do not surface absolute host paths; use \`workspaceRoot\`-relative paths only.`,
			]
		: [
				`Do not introduce project-specific code; \`@mcp-vertex/core\` is project-agnostic.`,
				`Do not read files via \`node:fs\`; always go through the \`IFileReader\` abstraction.`,
			];
	const tokenHotspots: string[] = [];
	const srcDir = join(REPO_ROOT, scope.dir, 'src');
	try {
		const entries = await readdir(srcDir, { withFileTypes: true });
		for (const entry of entries) {
			if (entry.isFile() && /\.(schema|tools)\.ts$/.test(entry.name)) {
				tokenHotspots.push(
					relative(REPO_ROOT, join(srcDir, entry.name)),
				);
				if (tokenHotspots.length >= MAX_HOTSPOTS) break;
			}
		}
	} catch {
		// src/ missing — leave empty.
	}
	const summary = scope.isPlugin
		? (
				await readPluginManifest(
					join(REPO_ROOT, scope.dir, 'plugin.manifest.ts'),
				)
			).summary
		: pkg.description;
	const purpose = (
		summary ??
		pkg.description ??
		`mcp-vertex ${scope.isPlugin ? 'plugin' : 'package'} ${pkg.name ?? scope.dir}`
	).slice(0, 280);
	return {
		purpose,
		public: publicSymbols,
		depends,
		writes,
		entry,
		tests,
		doNot,
		tokenHotspots,
	};
};

const bullet = (text: string): string => `- ${text}`;
const section = (title: string, body: readonly string[] | string): string => {
	const list = Array.isArray(body) ? body : [body];
	if (list.length === 0) return `## ${title}\n\n_(none)_\n`;
	return `## ${title}\n\n${list.map(bullet).join('\n')}\n`;
};

/** Render an AGENT.md block (just the marker-delimited region). */
export const renderAgentMdBlock = (sections: IAgentMdSections): string => {
	const out: string[] = [
		MARKER_BEGIN,
		section('Purpose', sections.purpose),
		section('Public API', sections.public),
		section('Depends on', sections.depends),
		section('Writes', sections.writes),
		section('Entry points', sections.entry),
		section('Tests', sections.tests),
		section('Do not', sections.doNot),
		section('Token hotspots', sections.tokenHotspots),
		MARKER_END,
	];
	return `${out.join('\n')}\n`;
};

/**
 * Compose + write the AGENT.md for every package and plugin in the
 * repo. Returns the list of touched files (workspace-relative).
 */
export const generateAll = async (): Promise<readonly string[]> => {
	const touched: string[] = [];
	const packages = await listDirs(join(REPO_ROOT, 'packages'));
	for (const name of packages) {
		const scope: IAgentScope = {
			dir: `packages/${name}`,
			packageJson: `packages/${name}/package.json`,
			isPlugin: false,
		};
		const sections = await composeAgentMd(scope);
		await writeAgentMd(scope, sections);
		touched.push(`${scope.dir}/AGENT.md`);
	}
	const plugins = await listDirs(join(REPO_ROOT, 'plugins'));
	for (const name of plugins) {
		const scope: IAgentScope = {
			dir: `plugins/${name}`,
			packageJson: `plugins/${name}/package.json`,
			isPlugin: true,
		};
		const sections = await composeAgentMd(scope);
		await writeAgentMd(scope, sections);
		touched.push(`${scope.dir}/AGENT.md`);
	}
	return touched;
};

const writeAgentMd = async (
	scope: IAgentScope,
	sections: IAgentMdSections,
): Promise<void> => {
	const target = join(REPO_ROOT, scope.dir, 'AGENT.md');
	const block = renderAgentMdBlock(sections);
	const existing = await readText(target);
	if (existing.includes(MARKER_BEGIN) && existing.includes(MARKER_END)) {
		// Update the block in place; preserve hand-edited prose
		// below the marker.
		const prologue = existing.slice(0, existing.indexOf(MARKER_BEGIN));
		const epilogue = existing.slice(
			existing.indexOf(MARKER_END) + MARKER_END.length,
		);
		const next = `${prologue}${block}${epilogue}`.replace(
			/\n{3,}/g,
			'\n\n',
		);
		await writeFile(target, next);
		return;
	}
	// Fresh file: write the block followed by an instructional
	// stub for hand-edited content.
	const header = [
		`# AGENT.md — ${scope.isPlugin ? 'plugin' : 'package'} \`${scope.dir}\``,
		'',
		'> Below the `<!-- mcp-vertex:begin agent-md -->` marker is',
		'> generated. Edit prose ONLY outside that block — the',
		'> regenerator will replace the block verbatim.',
		'',
		'',
	].join('\n');
	await writeFile(target, `${header}${block}\n`);
};

export const main = async (argv: readonly string[]): Promise<number> => {
	void argv;
	const touched = await generateAll();
	for (const rel of touched) {
		process.stdout.write(`gen:agent-md → ${rel}\n`);
	}
	process.stdout.write(
		`\ngen:agent-md: wrote ${touched.length} AGENT.md(s)\n`,
	);
	return 0;
};

if (import.meta.main) {
	process.exit(await main(process.argv.slice(2)));
}
